#!/usr/bin/env node
/* eslint-disable */
/**
 * Produce a hand-editable static build of the site.
 *
 * Steps:
 *  1. Run Create React App's production build.
 *  2. Copy the `build/` output into `docs/` (wiping any previous contents).
 *  3. Strip sourcemaps — they bloat the output and aren't needed to serve.
 *  4. Run prettier over every HTML and CSS file so a human can read and
 *     tweak them directly. The JS bundle is left alone (it's generated by
 *     webpack; edit source in `src/` for code changes).
 *  5. Drop `.nojekyll` so GitHub Pages doesn't rewrite filenames beginning
 *     with an underscore, and a short `README.md` explaining the folder.
 *
 * The CI workflow at `.github/workflows/deploy-pages.yml` runs this on
 * every push to master and deploys `docs/` to GitHub Pages
 * (nesarahippla.com).
 */
const { execSync } = require('child_process');
const fs = require('fs');
const path = require('path');

const ROOT = path.resolve(__dirname, '..');
const BUILD_DIR = path.join(ROOT, 'build');
const DOCS_DIR = path.join(ROOT, 'docs');

function run(cmd, opts = {}) {
  console.log(`\n$ ${cmd}`);
  execSync(cmd, { stdio: 'inherit', cwd: ROOT, ...opts });
}

function rimraf(p) {
  if (!fs.existsSync(p)) return;
  fs.rmSync(p, { recursive: true, force: true });
}

function copyDir(src, dst) {
  fs.mkdirSync(dst, { recursive: true });
  for (const entry of fs.readdirSync(src, { withFileTypes: true })) {
    const s = path.join(src, entry.name);
    const d = path.join(dst, entry.name);
    if (entry.isDirectory()) copyDir(s, d);
    else fs.copyFileSync(s, d);
  }
}

// Skips docs/apps/: those are finished builds from other repos (see
// scripts/build-apps.sh) and their minified HTML isn't ours to reformat.
function walk(dir, match, out = []) {
  for (const entry of fs.readdirSync(dir, { withFileTypes: true })) {
    const p = path.join(dir, entry.name);
    if (entry.isDirectory()) {
      if (p !== path.join(DOCS_DIR, 'apps')) walk(p, match, out);
    } else if (match.test(entry.name)) out.push(p);
  }
  return out;
}

(async () => {
  console.log('▶ Building app with react-scripts...');
  run('npm run build', { env: { ...process.env, CI: 'false' } });

  console.log('▶ Resetting docs/ ...');
  rimraf(DOCS_DIR);
  copyDir(BUILD_DIR, DOCS_DIR);

  // Strip sourcemaps + their trailing references.
  for (const m of walk(DOCS_DIR, /\.map$/)) fs.unlinkSync(m);
  for (const file of walk(DOCS_DIR, /\.(js|css)$/)) {
    const cleaned = fs
      .readFileSync(file, 'utf8')
      .replace(/\n?\/[\/\*]# sourceMappingURL=.*$/m, '');
    fs.writeFileSync(file, cleaned);
  }

  console.log('▶ Prettifying HTML and CSS files ...');
  const prettier = require('prettier');
  for (const file of walk(DOCS_DIR, /\.(html|css)$/)) {
    const parser = file.endsWith('.html') ? 'html' : 'css';
    const formatted = await prettier.format(fs.readFileSync(file, 'utf8'), {
      parser,
      printWidth: 100,
      htmlWhitespaceSensitivity: 'ignore',
    });
    fs.writeFileSync(file, formatted);
    console.log('   formatted', path.relative(ROOT, file));
  }

  fs.writeFileSync(path.join(DOCS_DIR, '.nojekyll'), '');
  fs.copyFileSync(path.join(DOCS_DIR, 'index.html'), path.join(DOCS_DIR, '404.html'));
  fs.writeFileSync(
    path.join(DOCS_DIR, 'README.md'),
    `# Published site\n\nThis folder is generated by \`npm run build:static\` from the source in\n\`rORrEtboLt/nesarahippladotcom\`. For code or content changes, edit\nsource there — hand edits here will be overwritten on the next deploy.\n`
  );

  console.log('\n✔ docs/ is ready.');
})().catch((err) => {
  console.error(err);
  process.exit(1);
});
